update nexora.modules set description='Aprenda Java e orientação a objetos por meio de tipos, métodos, classes, encapsulamento, composição, interfaces, collections, exceções e um projeto completo.' where course_id=(select id from nexora.courses where slug='programador-master') and position=8;
update nexora.lessons set objective='Explicar a relação entre código Java, bytecode, JVM e JDK e reconhecer o papel da compilação no ciclo de desenvolvimento.',estimated_minutes=32,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"O que a JVM executa normalmente?","options":["Bytecode Java.","CSS.","SQL diretamente."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um arquivo .java foi escrito, mas executar diretamente sem compilação ou ambiente correto falha."},{"type":"concept","title":"Java e a JVM","body":"Java normalmente é compilado para bytecode, que a JVM executa. O JDK inclui ferramentas de desenvolvimento como compilador e runtime. Essa camada intermediária ajuda a portabilidade: o bytecode pode rodar em diferentes sistemas com JVM compatível. Entender compilação e execução evita confundir erro de sintaxe, erro de compilação e erro em runtime."},{"type":"mechanics","title":"Como aplicar","items":["Diferencie JDK, JVM e bytecode.","Leia erros de compilação antes de executar.","Confirme versão do JDK do projeto.","Não misture dependências de versões sem necessidade."]},{"type":"example","title":"Exemplo","body":"javac App.java\\njava App","language":"java"},{"type":"mistake","title":"Erro comum","body":"Interpretar qualquer falha como ''bug no código'' quando o problema pode ser versão do JDK ou classpath."},{"type":"guided","question":"O que a JVM executa normalmente?","options":["Bytecode Java.","CSS.","SQL diretamente."],"answer":0,"hint":"Escolha a alternativa coerente com o modelo orientado a objetos.","feedback":"Correto. A escolha mantém responsabilidades claras.","feedback_incorrect":"Revise o contrato e o exemplo."},{"type":"recap","items":["Explicar a relação entre código Java, bytecode, JVM e JDK e reconhecer o papel da compilação no ciclo de desenvolvimento.","Diferencie JDK, JVM e bytecode.","Leia erros de compilação antes de executar.","Confirme versão do JDK do projeto."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=8) and title='Java e a JVM';
update nexora.lessons set objective='Criar uma classe Java com método main e organizar arquivos em estrutura de projeto previsível.',estimated_minutes=36,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual método é o ponto de entrada clássico de uma aplicação Java?","options":["public static void main","render","SELECT"],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O código compila em um arquivo solto, mas o projeto precisa crescer e ser entendido por outras pessoas."},{"type":"concept","title":"Primeiro programa e estrutura de projeto","body":"O ponto de entrada clássico de uma aplicação Java é o método public static void main. Classes vivem em arquivos e, em projetos maiores, pacotes organizam namespaces. A estrutura deve refletir responsabilidades, não apenas acumular classes na raiz. Ferramentas de build podem padronizar src, dependências e execução."},{"type":"mechanics","title":"Como aplicar","items":["Entenda assinatura do main.","Use nomes de classes em PascalCase.","Organize código fonte em diretórios coerentes.","Não crie pacote diferente para cada classe sem propósito."]},{"type":"example","title":"Exemplo","body":"public class App {\\n  public static void main(String[] args) {\\n    System.out.println(\"Olá, Java\");\\n  }\\n}","language":"java"},{"type":"mistake","title":"Erro comum","body":"Criar toda a aplicação dentro do main. O método deve orquestrar, não concentrar todas as regras."},{"type":"guided","question":"Qual método é o ponto de entrada clássico de uma aplicação Java?","options":["public static void main","render","SELECT"],"answer":0,"hint":"Escolha a alternativa coerente com o modelo orientado a objetos.","feedback":"Correto. A escolha mantém responsabilidades claras.","feedback_incorrect":"Revise o contrato e o exemplo."},{"type":"recap","items":["Criar uma classe Java com método main e organizar arquivos em estrutura de projeto previsível.","Entenda assinatura do main.","Use nomes de classes em PascalCase.","Organize código fonte em diretórios coerentes."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=8) and title='Primeiro programa e estrutura de projeto';
update nexora.lessons set objective='Declarar variáveis com tipos primitivos e referências e construir expressões respeitando conversões e limites de tipo.',estimated_minutes=38,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual tipo representa verdadeiro/falso em Java?","options":["boolean","int","String apenas"],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Uma divisão entre inteiros retorna resultado truncado e o programa esperava decimal."},{"type":"concept","title":"Variáveis, tipos e operadores","body":"Java possui tipagem estática. Tipos primitivos incluem int, long, double, boolean e char; objetos são referências. O compilador verifica compatibilidade antes da execução. Operações entre tipos seguem regras de promoção e divisão inteira precisa ser considerada. Tipos tornam contratos mais explícitos, mas ainda é preciso escolher representação adequada ao domínio."},{"type":"mechanics","title":"Como aplicar","items":["Escolha tipo pelo intervalo e significado.","Entenda divisão inteira.","Evite conversões forçadas sem validar perda.","Use boolean para condições claras."]},{"type":"example","title":"Exemplo","body":"int quantidade=3;\\ndouble preco=19.90;\\ndouble total=quantidade*preco;","language":"java"},{"type":"mistake","title":"Erro comum","body":"Usar double para todo valor monetário sem considerar precisão e requisitos do domínio."},{"type":"guided","question":"Qual tipo representa verdadeiro/falso em Java?","options":["boolean","int","String apenas"],"answer":0,"hint":"Escolha a alternativa coerente com o modelo orientado a objetos.","feedback":"Correto. A escolha mantém responsabilidades claras.","feedback_incorrect":"Revise o contrato e o exemplo."},{"type":"recap","items":["Declarar variáveis com tipos primitivos e referências e construir expressões respeitando conversões e limites de tipo.","Escolha tipo pelo intervalo e significado.","Entenda divisão inteira.","Evite conversões forçadas sem validar perda."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=8) and title='Variáveis, tipos e operadores';
update nexora.lessons set objective='Implementar decisões e laços em Java preservando as regras modeladas e garantindo condições de parada.',estimated_minutes=40,lab_type='pseudocode',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Uma regra de frete já foi validada em lógica e agora precisa ser traduzida para Java."},{"type":"concept","title":"Condições e repetição","body":"if/else, switch e laços for/while implementam o mesmo raciocínio lógico estudado antes. A diferença principal é a sintaxe e os tipos. O objetivo é preservar a regra, não reescrevê-la de forma mais complexa. Laços sobre coleções podem usar for-each quando o índice não é necessário."},{"type":"mechanics","title":"Como aplicar","items":["Traduza a regra já testada.","Use else quando os ramos são exclusivos.","Escolha for-each para percorrer valores.","Teste limites e coleção vazia."]},{"type":"example","title":"Exemplo","body":"if (total >= 200) {\\n  frete = 0;\\n} else {\\n  frete = 20;\\n}","language":"java"},{"type":"mistake","title":"Erro comum","body":"Alterar a regra ao traduzir para sintaxe nova — por exemplo trocar >= por > sem perceber."},{"type":"guided","question":"Qual operador preserva ''a partir de 200''?","options":[">=",">","!="],"answer":0,"hint":"Escolha a alternativa coerente com o modelo orientado a objetos.","feedback":"Correto. A escolha mantém responsabilidades claras.","feedback_incorrect":"Revise o contrato e o exemplo."},{"type":"recap","items":["Implementar decisões e laços em Java preservando as regras modeladas e garantindo condições de parada.","Traduza a regra já testada.","Use else quando os ramos são exclusivos.","Escolha for-each para percorrer valores."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=8) and title='Condições e repetição';
update nexora.lessons set objective='Extrair comportamento em métodos com parâmetros, retorno e visibilidade adequada, reduzindo duplicação.',estimated_minutes=42,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Quando um método pode ser static com naturalidade?","options":["Quando não depende do estado de uma instância.","Quando precisa acessar campos de cada objeto.","Sempre."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"A mesma regra de cálculo aparece em diferentes partes de uma classe."},{"type":"concept","title":"Métodos e parâmetros","body":"Métodos agrupam comportamento. A assinatura comunica nome, parâmetros e tipo de retorno. Métodos pequenos ajudam a testar e reutilizar regras. static pertence à classe e pode ser útil para funções sem estado de instância; métodos de instância operam sobre objetos. A escolha deve refletir o modelo, não preferência aleatória."},{"type":"mechanics","title":"Como aplicar","items":["Nomeie método pela ação.","Passe dados necessários por parâmetros.","Retorne resultado em vez de alterar estado distante.","Use static somente quando não depende de instância."]},{"type":"example","title":"Exemplo","body":"static double calcularTotal(double preco,int qtd){\\n  return preco*qtd;\\n}","language":"java"},{"type":"mistake","title":"Erro comum","body":"Criar métodos que recebem dezenas de parâmetros porque o modelo de dados não foi estruturado."},{"type":"guided","question":"Quando um método pode ser static com naturalidade?","options":["Quando não depende do estado de uma instância.","Quando precisa acessar campos de cada objeto.","Sempre."],"answer":0,"hint":"Escolha a alternativa coerente com o modelo orientado a objetos.","feedback":"Correto. A escolha mantém responsabilidades claras.","feedback_incorrect":"Revise o contrato e o exemplo."},{"type":"recap","items":["Extrair comportamento em métodos com parâmetros, retorno e visibilidade adequada, reduzindo duplicação.","Nomeie método pela ação.","Passe dados necessários por parâmetros.","Retorne resultado em vez de alterar estado distante."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=8) and title='Métodos e parâmetros';
update nexora.lessons set objective='Modelar entidades com classes que agrupem estado e comportamento e criar objetos com responsabilidades claras.',estimated_minutes=46,lab_type='data_model',lab_config='{"data_model":{"scenario":"Classifique os elementos do modelo orientado a objetos.","options":["Classe","Objeto","Campo","Método"],"rows":[{"label":"Produto","value":"modelo","answer":0},{"label":"novo Produto(...)","value":"instância","answer":1},{"label":"preco","value":"estado","answer":2},{"label":"calcularDesconto()","value":"comportamento","answer":3}],"feedback":"Boa modelagem: tipo, instância, estado e comportamento foram diferenciados."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Dados de produto estão espalhados em várias variáveis e funções sem um lugar que represente o conceito ''Produto''."},{"type":"concept","title":"Classes e objetos","body":"Classe define uma estrutura e comportamento; objeto é uma instância concreta. Campos representam estado e métodos operam sobre ele. Modelagem orientada a objetos é útil quando conceitos do domínio têm identidade, estado e comportamento relacionados. Nem toda função precisa virar classe, mas entidades centrais ganham clareza quando suas invariantes ficam próximas dos dados."},{"type":"mechanics","title":"Como aplicar","items":["Modele conceitos do domínio, não telas.","Agrupe estado que pertence à mesma entidade.","Coloque comportamento relacionado perto do estado.","Evite classes que são apenas sacos de dados sem necessidade."]},{"type":"example","title":"Exemplo","body":"class Produto {\\n  String nome;\\n  double preco;\\n  boolean ativo;\\n}","language":"java"},{"type":"mistake","title":"Erro comum","body":"Criar uma classe para cada função e aumentar complexidade sem ganhar coesão."},{"type":"guided","question":"O que é um objeto?","options":["Uma instância de uma classe.","Um arquivo CSS.","Uma query SQL."],"answer":0,"hint":"Escolha a alternativa coerente com o modelo orientado a objetos.","feedback":"Correto. A escolha mantém responsabilidades claras.","feedback_incorrect":"Revise o contrato e o exemplo."},{"type":"recap","items":["Modelar entidades com classes que agrupem estado e comportamento e criar objetos com responsabilidades claras.","Modele conceitos do domínio, não telas.","Agrupe estado que pertence à mesma entidade.","Coloque comportamento relacionado perto do estado."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=8) and title='Classes e objetos';
update nexora.lessons set objective='Inicializar objetos em estado válido com construtores e proteger invariantes usando encapsulamento e métodos apropriados.',estimated_minutes=46,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual é um benefício do encapsulamento?","options":["Proteger invariantes do objeto.","Eliminar todos os métodos.","Substituir banco de dados."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um Produto pode ser criado com preço negativo e só quebra muito depois."},{"type":"concept","title":"Construtores e encapsulamento","body":"Construtores estabelecem estado inicial. Encapsulamento controla como campos são lidos ou alterados, permitindo validar invariantes. Tornar tudo public reduz proteção do modelo. Getters/setters não devem ser gerados automaticamente sem pensar: algumas mudanças precisam de métodos com intenção, como aplicarDesconto ou ativar."},{"type":"mechanics","title":"Como aplicar","items":["Valide invariantes na criação.","Restrinja acesso direto quando necessário.","Use métodos de domínio para mudanças significativas.","Não crie setters para tudo por reflexo."]},{"type":"example","title":"Exemplo","body":"class Produto {\\n  private double preco;\\n  Produto(double preco){\\n    if(preco<0) throw new IllegalArgumentException();\\n    this.preco=preco;\\n  }\\n}","language":"java"},{"type":"mistake","title":"Erro comum","body":"Encapsulamento apenas nominal: campos private com setters públicos sem qualquer regra preservam o mesmo problema."},{"type":"guided","question":"Qual é um benefício do encapsulamento?","options":["Proteger invariantes do objeto.","Eliminar todos os métodos.","Substituir banco de dados."],"answer":0,"hint":"Escolha a alternativa coerente com o modelo orientado a objetos.","feedback":"Correto. A escolha mantém responsabilidades claras.","feedback_incorrect":"Revise o contrato e o exemplo."},{"type":"recap","items":["Inicializar objetos em estado válido com construtores e proteger invariantes usando encapsulamento e métodos apropriados.","Valide invariantes na criação.","Restrinja acesso direto quando necessário.","Use métodos de domínio para mudanças significativas."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=8) and title='Construtores e encapsulamento';
update nexora.lessons set objective='Comparar herança e composição e escolher a relação que representa melhor o domínio sem criar hierarquias rígidas.',estimated_minutes=48,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Relatorio que usa Exportador representa melhor:","options":["Composição.","Herança obrigatória.","Interface gráfica."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Uma classe Relatorio precisa usar um ExportadorPDF. Isso é ''é um'' ou ''tem um''?"},{"type":"concept","title":"Herança e composição","body":"Herança representa relação é-um e permite especialização; composição representa tem-um e combina objetos. Herança pode reutilizar código, mas também acopla subclasses à hierarquia. Composição tende a ser flexível quando comportamentos podem variar ou ser trocados. A escolha deve começar pelo significado do domínio, não por economia de linhas."},{"type":"mechanics","title":"Como aplicar","items":["Use herança quando a substituição semântica é verdadeira.","Prefira composição para capacidades intercambiáveis.","Evite hierarquias profundas.","Não herde apenas para acessar métodos utilitários."]},{"type":"example","title":"Exemplo","body":"class Relatorio {\\n  private Exportador exportador;\\n  Relatorio(Exportador exportador){this.exportador=exportador;}\\n}","language":"java"},{"type":"mistake","title":"Erro comum","body":"Criar herança para reutilizar duas funções, mesmo quando as classes não têm relação ''é um''."},{"type":"guided","question":"Relatorio que usa Exportador representa melhor:","options":["Composição.","Herança obrigatória.","Interface gráfica."],"answer":0,"hint":"Escolha a alternativa coerente com o modelo orientado a objetos.","feedback":"Correto. A escolha mantém responsabilidades claras.","feedback_incorrect":"Revise o contrato e o exemplo."},{"type":"recap","items":["Comparar herança e composição e escolher a relação que representa melhor o domínio sem criar hierarquias rígidas.","Use herança quando a substituição semântica é verdadeira.","Prefira composição para capacidades intercambiáveis.","Evite hierarquias profundas."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=8) and title='Herança e composição';
update nexora.lessons set objective='Definir contratos com interfaces e usar polimorfismo para trocar implementações sem alterar o consumidor.',estimated_minutes=50,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual benefício do polimorfismo?","options":["Trocar implementações mantendo o mesmo contrato.","Eliminar tipos.","Impedir testes."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O sistema precisa enviar notificações por e-mail hoje e WhatsApp amanhã sem reescrever a regra de pedido."},{"type":"concept","title":"Polimorfismo e interfaces","body":"Uma interface define um contrato de comportamento. Diferentes classes podem implementá-lo e ser usadas por código que depende apenas do contrato. Polimorfismo permite tratar implementações diferentes de forma uniforme. Isso reduz acoplamento quando existe uma variação real e testável, mas interfaces vazias ou criadas antecipadamente podem só aumentar indirection."},{"type":"mechanics","title":"Como aplicar","items":["Crie interface em torno de uma capacidade real.","Dependa do contrato quando precisa trocar implementação.","Mantenha interface pequena e coesa.","Evite abstração sem mais de uma necessidade concreta."]},{"type":"example","title":"Exemplo","body":"interface Notificador { void enviar(String msg); }\\nclass EmailNotificador implements Notificador { ... }","language":"java"},{"type":"mistake","title":"Erro comum","body":"Criar interface para cada classe apenas por padrão arquitetural, sem benefício de substituição."},{"type":"guided","question":"Qual benefício do polimorfismo?","options":["Trocar implementações mantendo o mesmo contrato.","Eliminar tipos.","Impedir testes."],"answer":0,"hint":"Escolha a alternativa coerente com o modelo orientado a objetos.","feedback":"Correto. A escolha mantém responsabilidades claras.","feedback_incorrect":"Revise o contrato e o exemplo."},{"type":"recap","items":["Definir contratos com interfaces e usar polimorfismo para trocar implementações sem alterar o consumidor.","Crie interface em torno de uma capacidade real.","Dependa do contrato quando precisa trocar implementação.","Mantenha interface pequena e coesa."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=8) and title='Polimorfismo e interfaces';
update nexora.lessons set objective='Escolher List, Set ou Map conforme ordem, unicidade e acesso por chave e usar generics para manter tipos explícitos.',estimated_minutes=48,lab_type='data_model',lab_config='{"data_model":{"scenario":"Escolha a coleção que melhor representa cada necessidade.","options":["List","Set","Map","Array fixo"],"rows":[{"label":"Pedidos em ordem","value":"coleção","answer":0},{"label":"E-mails únicos","value":"coleção","answer":1},{"label":"Produto por ID","value":"índice","answer":2},{"label":"Coordenadas com tamanho fixo","value":"estrutura","answer":3}],"feedback":"A estrutura escolhida acompanha ordem, unicidade, chave e tamanho."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Você precisa armazenar uma sequência de pedidos, um conjunto de e-mails únicos e um índice de produtos por ID."},{"type":"concept","title":"Collections: List, Set e Map","body":"List preserva sequência e permite duplicatas; Set representa valores únicos; Map associa chave a valor. Generics como List<Produto> tornam o tipo dos elementos explícito e reduzem casts. A escolha correta simplifica algoritmos: não faz sentido simular busca por chave percorrendo lista se o domínio pede um mapa."},{"type":"mechanics","title":"Como aplicar","items":["Use List para sequência.","Use Set para unicidade.","Use Map para acesso por chave.","Declare generics específicos."]},{"type":"example","title":"Exemplo","body":"List<Pedido> pedidos=new ArrayList<>();\\nSet<String> emails=new HashSet<>();\\nMap<Long,Produto> porId=new HashMap<>();","language":"java"},{"type":"mistake","title":"Erro comum","body":"Usar List para tudo e implementar manualmente unicidade e índices."},{"type":"guided","question":"Qual coleção é adequada para valores únicos?","options":["Set","List necessariamente","Map sem chave"],"answer":0,"hint":"Escolha a alternativa coerente com o modelo orientado a objetos.","feedback":"Correto. A escolha mantém responsabilidades claras.","feedback_incorrect":"Revise o contrato e o exemplo."},{"type":"recap","items":["Escolher List, Set ou Map conforme ordem, unicidade e acesso por chave e usar generics para manter tipos explícitos.","Use List para sequência.","Use Set para unicidade.","Use Map para acesso por chave."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=8) and title='Collections: List, Set e Map';
update nexora.lessons set objective='Lançar e capturar exceções quando uma operação não pode cumprir seu contrato, preservando contexto e evitando captura genérica excessiva.',estimated_minutes=46,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Onde uma exceção deve ser capturada?","options":["Onde existe estratégia real de tratamento.","Sempre imediatamente.","Nunca."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Leitura de arquivo pode falhar; em outro caso, preço negativo viola regra de domínio."},{"type":"concept","title":"Exceções e tratamento de erros","body":"Exceções representam falhas que interrompem o fluxo normal. Checked e unchecked têm papéis diferentes no ecossistema Java, mas a decisão principal é: quem consegue tratar a falha com contexto suficiente? Capture onde existe recuperação ou tradução adequada. Não engula exceções; preserve causa e mensagem para diagnóstico."},{"type":"mechanics","title":"Como aplicar","items":["Lance exceção perto da violação.","Capture onde existe estratégia de tratamento.","Evite catch(Exception) indiscriminado.","Não exponha detalhes internos ao usuário final."]},{"type":"example","title":"Exemplo","body":"try {\\n  carregarArquivo();\\n} catch(IOException e) {\\n  logger.error(\"Falha ao carregar\",e);\\n}","language":"java"},{"type":"mistake","title":"Erro comum","body":"catch(Exception e){} para ''evitar que o programa pare''. Isso esconde falhas e pode manter estado inválido."},{"type":"guided","question":"Onde uma exceção deve ser capturada?","options":["Onde existe estratégia real de tratamento.","Sempre imediatamente.","Nunca."],"answer":0,"hint":"Escolha a alternativa coerente com o modelo orientado a objetos.","feedback":"Correto. A escolha mantém responsabilidades claras.","feedback_incorrect":"Revise o contrato e o exemplo."},{"type":"recap","items":["Lançar e capturar exceções quando uma operação não pode cumprir seu contrato, preservando contexto e evitando captura genérica excessiva.","Lance exceção perto da violação.","Capture onde existe estratégia de tratamento.","Evite catch(Exception) indiscriminado."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=8) and title='Exceções e tratamento de erros';
update nexora.lessons set objective='Ler e escrever arquivos com APIs modernas e fechamento seguro de recursos, controlando encoding e falhas.',estimated_minutes=48,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual API moderna representa caminhos em Java?","options":["Path","System.out apenas","Math"],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um arquivo é aberto e não fechado quando ocorre exceção, causando vazamento de recurso."},{"type":"concept","title":"Entrada, saída e arquivos","body":"Java oferece APIs como Files e Path para operações de arquivo. try-with-resources fecha recursos automaticamente. Texto deve declarar charset quando relevante. Caminhos devem ser construídos com APIs próprias, não concatenação manual de separadores. Entrada externa precisa de validação antes de definir destino de escrita."},{"type":"mechanics","title":"Como aplicar","items":["Use Path/Files.","Use try-with-resources quando abrir streams.","Declare charset.","Valide caminho antes de sobrescrever."]},{"type":"example","title":"Exemplo","body":"Path p=Path.of(\"dados\",\"clientes.txt\");\\nString texto=Files.readString(p,StandardCharsets.UTF_8);","language":"java"},{"type":"mistake","title":"Erro comum","body":"Concatenar \"dados/\" + nome vindo do usuário sem validar e permitir path traversal."},{"type":"guided","question":"Qual API moderna representa caminhos em Java?","options":["Path","System.out apenas","Math"],"answer":0,"hint":"Escolha a alternativa coerente com o modelo orientado a objetos.","feedback":"Correto. A escolha mantém responsabilidades claras.","feedback_incorrect":"Revise o contrato e o exemplo."},{"type":"recap","items":["Ler e escrever arquivos com APIs modernas e fechamento seguro de recursos, controlando encoding e falhas.","Use Path/Files.","Use try-with-resources quando abrir streams.","Declare charset."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=8) and title='Entrada, saída e arquivos';
update nexora.lessons set objective='Organizar classes em pacotes por responsabilidade e aplicar convenções que reduzam acoplamento e tornem o projeto navegável.',estimated_minutes=48,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual sinal indica boa organização?","options":["É fácil localizar a responsabilidade de uma mudança.","Tudo fica em utils.","Toda classe é public."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Todas as classes vivem em um pacote utils e ninguém sabe onde uma regra deveria ser alterada."},{"type":"concept","title":"Organização em pacotes e boas práticas","body":"Pacotes criam namespaces e ajudam a organizar responsabilidades. Uma estrutura por domínio ou capacidade costuma comunicar melhor que pastas genéricas cheias de utilitários. Convenções de nomes, visibilidade mínima e dependências direcionadas tornam o projeto mais fácil de manter. Boas práticas são meios para reduzir custo de mudança, não regras decorativas."},{"type":"mechanics","title":"Como aplicar","items":["Agrupe por responsabilidade/domínio.","Evite pacote utils como destino de tudo.","Use visibilidade mínima necessária.","Mantenha dependências em direção clara."]},{"type":"example","title":"Exemplo","body":"br.com.lc.pedidos\\n  Pedido.java\\n  PedidoService.java\\n  PedidoRepository.java","language":"text"},{"type":"mistake","title":"Erro comum","body":"Criar pacotes apenas por tipo técnico e espalhar uma feature em dezenas de locais sem necessidade."},{"type":"guided","question":"Qual sinal indica boa organização?","options":["É fácil localizar a responsabilidade de uma mudança.","Tudo fica em utils.","Toda classe é public."],"answer":0,"hint":"Escolha a alternativa coerente com o modelo orientado a objetos.","feedback":"Correto. A escolha mantém responsabilidades claras.","feedback_incorrect":"Revise o contrato e o exemplo."},{"type":"recap","items":["Organizar classes em pacotes por responsabilidade e aplicar convenções que reduzam acoplamento e tornem o projeto navegável.","Agrupe por responsabilidade/domínio.","Evite pacote utils como destino de tudo.","Use visibilidade mínima necessária."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=8) and title='Organização em pacotes e boas práticas';
update nexora.lessons set objective='Construir uma aplicação Java orientada a objetos com modelo de domínio, coleções, persistência simples e tratamento de erros, documentada e testável.',estimated_minutes=75,lab_type='project',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"A entrega precisa demonstrar OOP aplicada a um problema real, não apenas uma coleção de classes sem fluxo."},{"type":"concept","title":"Projeto: aplicação Java orientada a objetos","body":"O projeto deve começar pelo domínio: entidades, regras e casos de uso. Depois, modele classes e contratos, escolha coleções, trate erros e adicione entrada/saída. A aplicação pode ser de terminal, mas precisa ter fluxo completo e exemplos de uso. Testes ou cenários reproduzíveis devem provar regras importantes."},{"type":"mechanics","title":"Como aplicar","items":["Modele regras antes da interface.","Use encapsulamento para invariantes.","Escolha composição/herança conscientemente.","Inclua tratamento de erro e documentação."]},{"type":"example","title":"Exemplo","body":"Exemplo: sistema de biblioteca, estoque ou pedidos com entidades, serviços, coleções, persistência em arquivo e menu de terminal."},{"type":"mistake","title":"Erro comum","body":"Avaliar OOP pela quantidade de classes. Um modelo simples e coerente é melhor que dezenas de abstrações vazias."},{"type":"guided","question":"O que deve orientar as classes do projeto?","options":["Conceitos e regras do domínio.","Quantidade de arquivos desejada.","Cores da interface."],"answer":0,"hint":"Escolha a alternativa coerente com o modelo orientado a objetos.","feedback":"Correto. A escolha mantém responsabilidades claras.","feedback_incorrect":"Revise o contrato e o exemplo."},{"type":"recap","items":["Construir uma aplicação Java orientada a objetos com modelo de domínio, coleções, persistência simples e tratamento de erros, documentada e testável.","Modele regras antes da interface.","Use encapsulamento para invariantes.","Escolha composição/herança conscientemente."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=8) and title='Projeto: aplicação Java orientada a objetos';

